<script setup>
import { computed, reactive, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toEventDraft, toEventPayload } from '../domain/event-write.mjs';
const props = defineProps({ record: { type: Object, default: () => ({}) }, editing: Boolean, saving: Boolean, error: String, intakeMissing: { type: Array, default: () => [] }, intakeWarnings: { type: Array, default: () => [] } }); const emit = defineEmits(['cancel', 'save']); const draft = reactive({ ...toEventDraft(props.record) }); const localError = ref(''); const title = computed(() => props.editing ? 'Sửa sự kiện' : 'Thêm sự kiện'); const submitLabel = computed(() => props.editing ? 'Lưu thay đổi' : 'Lưu sự kiện'); const modes = [{ value: 'host', label: 'Tổ chức' }, { value: 'join', label: 'Tham gia' }]; const statuses = ['', 'Đang chuẩn bị', 'Đã diễn ra', 'Đã hủy'].map((value) => ({ value, label: value || 'Chọn trạng thái' })); watch(() => props.record, (record) => Object.assign(draft, toEventDraft(record)), { deep: true });
function submit() { try { localError.value = ''; emit('save', toEventPayload(draft)); } catch (error) { localError.value = error.message; } }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">{{ title }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Thông tin lõi; chi phí và tệp được quản lý ở bước riêng.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div v-if="intakeWarnings.length || intakeMissing.length" class="mx-5 mt-4 space-y-2 rounded-lg bg-[var(--mds-warning-bg)] p-3 text-[13px]"><p v-if="intakeWarnings.length"><strong>Cảnh báo khi đọc tệp:</strong> {{ intakeWarnings.join(' · ') }}</p><p v-if="intakeMissing.length"><strong>AI chưa thấy:</strong> {{ intakeMissing.join(', ') }}. Hãy kiểm tra trước khi lưu.</p></div><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Tên sự kiện *</span><MInput v-model="draft.name" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Hình thức</span><MSelect v-model="draft.mode" :options="modes" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Đơn vị tổ chức</span><MInput v-model="draft.organizer" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Thời gian bắt đầu</span><MInput v-model="draft.start_time" type="datetime-local" :disabled="saving" /></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Địa điểm</span><MInput v-model="draft.location" :disabled="saving" /></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :disabled="saving" /></label></div><p v-if="error || localError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" @click="submit">{{ submitLabel }}</MButton></footer></form></section></template>
